'use strict';
const customerView={routerId:'',q:'',category:'',connection:'',page:1,result:null,request:0};
function customerBadge(value){return `<span class="status ${['PPP connected','Hotspot connected','ARP reachable','Reporting'].includes(value)?'online':value.includes('disconnected')?'offline':value==='Report stale'?'warning':'pending'}">${h(value)}</span>`;}
function customerConnectionOptions(){return [['','All evidence'],['active','Active PPP / Hotspot sessions'],['disconnected','Disconnected sessions'],['stale','Stale reports']].map(([value,label])=>`<option value="${value}" ${customerView.connection===value?'selected':''}>${label}</option>`).join('');}
function renderCustomers(){
 $('#main').innerHTML=heading('Customer discovery','Identify customer equipment and connections observed by your MikroTiks.','<button class="button secondary" id="refresh-customers">Refresh observations</button>')+notice('Connection evidence','PPP connected and Hotspot connected mean reported active sessions. A bound DHCP lease or advertised neighbor does not prove Internet access. Classification is manual; these records are separate from TR-069 devices.')+`<section class="card"><div class="table-toolbar"><input type="search" id="customer-query" aria-label="Search discovered devices" placeholder="Name, IP, MAC or model" value="${h(customerView.q)}"><select id="customer-router" aria-label="Filter customer router"><option value="">All MikroTiks</option>${rows('devices').filter(d=>d.type==='router').map(d=>`<option value="${d.id}" ${customerView.routerId===d.id?'selected':''}>${h(d.name)}</option>`).join('')}</select><select id="customer-category" aria-label="Filter device category"><option value="">All categories</option></select><select id="customer-connection" aria-label="Filter connection evidence">${customerConnectionOptions()}</select></div><div id="customer-router-status"></div><div id="customer-results" aria-live="polite"><div class="list-empty">Loading observations…</div></div></section>`;
 $('#refresh-customers').onclick=()=>loadCustomers();let debounce;
 $('#customer-query').oninput=e=>{customerView.q=e.target.value;customerView.page=1;clearTimeout(debounce);debounce=setTimeout(()=>loadCustomers(),250);};
 $('#customer-router').onchange=e=>{customerView.routerId=e.target.value;customerView.page=1;loadCustomers();};
 $('#customer-category').onchange=e=>{customerView.category=e.target.value;customerView.page=1;loadCustomers();};
 $('#customer-connection').onchange=e=>{customerView.connection=e.target.value;customerView.page=1;loadCustomers();};
 loadCustomers();
}
async function loadCustomers(){
 const request=++customerView.request;try{const result=await api('customers?'+new URLSearchParams({routerId:customerView.routerId,q:customerView.q,category:customerView.category,connection:customerView.connection,page:customerView.page}));if(state.page!=='customers'||request!==customerView.request)return;customerView.result=result;customerView.page=result.page;
  $('#customer-category').innerHTML='<option value="">All categories</option>'+result.categories.map(c=>`<option ${customerView.category===c?'selected':''}>${h(c)}</option>`).join('');
  $('#customer-router-status').innerHTML=`<div class="customer-sources">${result.routers.map(r=>`<article><div class="cs-head"><strong>${h(r.name)}</strong> ${customerBadge(!r.configured?'Not enabled':!r.lastReport?'Awaiting first report':r.fresh?'Reporting':'Report stale')}</div><p>${h(stamp(r.lastReport))}${r.tables?' · '+Object.entries(r.tables).map(([s,t])=>h(s.toUpperCase()+': '+(!t.ok?'read failed':t.count+(t.truncated?' (limit reached)':'')))).join(' · '):''}</p>${NetworkPermissions.equipment(state.session.user.role)?`<div class="cs-actions"><button class="button secondary" data-customer-enable="${r.id}">${r.configured?'Replace discovery script':'Enable discovery'}</button>${r.configured?`<button class="button ghost danger" data-customer-disable="${r.id}">Disable reporting</button>`:''}</div>`:''}</article>`).join('')||'<p>Add a MikroTik first.</p>'}</div>`;
  $('#customer-results').innerHTML=table(['DEVICE / CATEGORY','MIKROTIK / ADDRESS','CONNECTION EVIDENCE','SUBSCRIBER TRAFFIC','LAST OBSERVED','ACTION'],result.items,d=>`<tr><td><strong>${h(d.name)}</strong><small>${h(d.category)}</small>${d.platform?'<small>'+h(d.platform+(d.model?' · '+d.model:''))+'</small>':''}</td><td>${h(d.routerName)}<small>${h(d.ips.join(', ')||'No IP advertised')}</small><small>${h(d.mac)}</small></td><td>${customerBadge(d.status)}<small>${h(d.evidence.map(e=>e.source.toUpperCase()).join(' · '))}</small></td><td>${d.traffic?`↓ ${d.traffic.downloadMbps.toFixed(3)} Mbps<br>↑ ${d.traffic.uploadMbps.toFixed(3)} Mbps`:'—'}</td><td>${h(stamp(d.lastObserved))}</td><td><button class="button secondary" data-customer-detail="${d.id}">Inspect</button></td></tr>`,'No matching observations. Enable discovery on a MikroTik to collect its existing customer records.')+`<div class="table-toolbar"><span>${result.total} device records · page ${result.page} of ${result.pages}</span><div class="setup-actions"><button class="button secondary" data-customer-page="${result.page-1}" ${result.page<=1?'disabled':''}>Previous</button><button class="button secondary" data-customer-page="${result.page+1}" ${result.page>=result.pages?'disabled':''}>Next</button></div></div>`;
 }catch(error){if(state.page==='customers'&&request===customerView.request)$('#customer-results').innerHTML=notice('Could not load customer discovery',h(error.message),true);}
}
function customerTrafficGraph(samples){if(samples.length<2)return '<p class="field-note">Traffic trend appears after repeated reports for the same PPP/Hotspot session with increasing router counters.</p>';const max=Math.max(0.01,...samples.flatMap(s=>[s.downloadMbps,s.uploadMbps])),first=samples[0].time,last=samples.at(-1).time,x=s=>40+(s.time-first)/Math.max(1,last-first)*650,y=v=>145-v/max*125,down=samples.map(s=>`${x(s)},${y(s.downloadMbps)}`).join(' '),up=samples.map(s=>`${x(s)},${y(s.uploadMbps)}`).join(' ');return `<svg class="graph" viewBox="0 0 720 180" role="img" aria-label="PPP or Hotspot traffic rates over time"><line class="gridline" x1="40" y1="20" x2="690" y2="20"/><line class="gridline" x1="40" y1="145" x2="690" y2="145"/><text x="2" y="25">${max.toFixed(2)}</text><text x="14" y="149">0</text><polyline class="series" points="${down}"/><polyline class="series secondary-series" points="${up}"/><text x="40" y="170">${h(new Date(first).toLocaleString())}</text><text x="520" y="170">${h(new Date(last).toLocaleString())}</text></svg><p class="field-note">↓ Download · ↑ Upload · Mbps · sampled about every 10 minutes (up to 7 days)</p>`;}
function customerHistoryTable(events){const names={first_seen:'First seen',returned:'Observed again',not_observed:'Not observed',ip_changed:'IP address changed',mac_changed:'MAC address changed',session_started:'Session started',session_ended:'Session ended'};return table(['EVENT','TIME','DETAILS'],events.slice().reverse(),e=>`<tr><td>${h(names[e.type]||e.type)}</td><td>${h(stamp(e.time))}</td><td>${h(e.details)}</td></tr>`,'No lifecycle changes recorded yet.');}
function customerDetails(id){const d=customerView.result?.items.find(x=>x.id===id);if(!d)return;const cpeCategory={'Customer router':'Customer router','ONT / ONU':'ONT / ONU','Access point':'Wi-Fi access point','Wireless radio':'Other CPE'}[d.category],existingCpe=rows('devices').find(x=>x.id===d.cpeId)||rows('devices').find(x=>x.type==='cpe'&&x.observedViaRouterId===d.routerId&&((d.mac&&x.macAddress===d.mac)||d.ips.some(ip=>ip===x.ip)));
 showDetails(d.name,`<p>${h(d.routerName)} · ${customerBadge(d.status)}</p><div class="detail-grid"><div><small>Classification</small><strong>${h(d.category)}</strong></div><div><small>First observed</small><strong style="font-size:13px">${h(stamp(d.firstObserved))}</strong></div><div><small>Last observed</small><strong style="font-size:13px">${h(stamp(d.lastObserved))}</strong></div></div>${table(['SOURCE','ADDRESS / MAC','REPORTED STATE','INTERFACE / SERVICE','OBSERVED'],d.evidence,e=>`<tr><td>${h(e.source.toUpperCase())}</td><td>${h(e.ip)}<small>${h(e.mac)}</small></td><td>${h(e.status)}${e.uptime?'<small>Session uptime: '+h(e.uptime)+'</small>':''}</td><td>${h(e.interface||e.service||'—')}</td><td>${h(stamp(e.observedAt))}</td></tr>`)}<p>Traffic is measured only when counters from the exact PPP interface or active Hotspot session are available in consecutive reports for the same session. Shared LAN interface traffic is never assigned to an individual DHCP client.</p>${cpeCategory&&NetworkPermissions.write(state.session.user.role,'devices','POST')?`<div class="setup-actions"><button class="button primary" data-customer-cpe="${d.id}" ${existingCpe?'data-existing-cpe="'+existingCpe.id+'"':''}>${existingCpe?'Open CPE inventory record':'Add to CPE onboarding'}</button></div><p class="field-note">Creates an unverified inventory record from this MikroTik observation. Confirm the device label and site with a customer or technician.</p>`:''}${NetworkPermissions.equipment(state.session.user.role)?`<form id="customer-label-form"><label>Display name<input name="name" maxlength="150" value="${h(d.name)}"></label><label>Device category<select name="category">${customerView.result.categories.map(c=>`<option ${d.category===c?'selected':''}>${h(c)}</option>`).join('')}</select></label><label>Notes<textarea name="notes" maxlength="1000">${h(d.notes)}</textarea></label><p class="form-error" id="customer-label-error"></p><button class="button primary" type="submit">Save classification</button></form>`:'<p>'+h(d.notes)+'</p>'}`);
 $('#detail-content').insertAdjacentHTML('beforeend',`<h3>PPP / Hotspot traffic trend</h3>${customerTrafficGraph(d.trafficHistory||[])}<h3>Device observation history</h3>${customerHistoryTable(d.history||[])}${d.cpeId?`<div class="notice"><div><strong>Linked CPE inventory</strong><br>Customer/account: ${h(d.customer||'Not recorded')}${d.linkedOnuName?'<br>Associated ONU record: '+h(d.linkedOnuName):'<br>No associated ONU record selected'} <button class="button secondary" data-edit-kind="devices" data-id="${d.cpeId}">Update CPE link</button></div></div>`:''}<p class="field-note">Traffic rates use counters from the same PPP or Hotspot session. A complete report can show when a known record stopped appearing; incomplete or truncated reports never mark devices missing.</p>`);
 const form=$('#customer-label-form');if(form)form.onsubmit=async event=>{event.preventDefault();const button=$('[type=submit]',form);button.disabled=true;try{await api('customers/'+id,'PATCH',Object.fromEntries(new FormData(form)));$('#detail-dialog').close();await loadCustomers();toast('Device classification saved');}catch(error){$('#customer-label-error').textContent=error.message;}finally{button.disabled=false;}};
}
function addCpeFromObservation(id,existingId){const d=customerView.result?.items.find(x=>x.id===id);if(!d)return;const category={'Customer router':'Customer router','ONT / ONU':'ONT / ONU','Access point':'Wi-Fi access point','Wireless radio':'Other CPE'}[d.category];if(!category)return;const note=`Imported from read-only observation on ${d.routerName}. First observed ${stamp(d.firstObserved)}; last observed ${stamp(d.lastObserved)}. Confirm serial, exact model and installation location with a customer or technician.`;$('#detail-dialog').close();openEditor('devices',existingId||null,{type:'cpe',driver:'none',name:d.name||d.mac||d.ips[0]||'Observed customer CPE',cpeCategory:category,vendor:d.platform||'',model:d.model||'',macAddress:d.mac||'',ip:d.ips[0]||'',observedViaRouterId:d.routerId,managementMethod:'Unknown',onboardingStatus:'Observed',notes:note});}
function customerEnrollment(id){const router=find('devices',id),prior=customerView.result?.routers.find(r=>r.id===id);if(!router)return;
 $('#editor-title').textContent='Customer discovery — '+router.name;$('#editor-description').textContent='Collect existing DHCP, ARP, active PPP, Hotspot and neighbor records every two minutes. No RouterOS update or reboot is required.';
 $('#editor-fields').innerHTML='<p>Installs only the Network Hub discovery script and scheduler. It reads network tables and sends observations over authenticated HTTPS to this workspace. It does not change customer services or fetch commands.</p>'+`<label class="check-label"><input type="checkbox" name="reviewed" required> Keep the script private and install it on ${h(router.name)}.</label>`+(prior?.configured?'<label class="check-label"><input type="checkbox" name="replace" required> Replace this discovery credential. The main router monitoring credential stays valid.</label>':'');
 $('#editor-error').textContent='';$('#editor-form [type=submit]').textContent='Generate discovery script';$('#editor').showModal();
 $('#editor-form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=$('[type=submit]',form);button.disabled=true;try{const result=await api('customer-agent/enroll','POST',{deviceId:id,replace:!!form.elements.replace?.checked});form.reset();$('#editor').close();await loadCustomers();showDetails('Discovery script — '+router.name,'<p>Install this private script through WinBox → System → Scripts or a RouterOS terminal. It contains a credential scoped to customer discovery for this MikroTik.</p><button class="button secondary" id="copy-discovery-script">Copy private script</button><label>Private discovery script<textarea id="customer-script-source" class="router-script-source" readonly rows="16" spellcheck="false">'+h(result.script)+'</textarea></label><p>After installation, close this window and refresh observations. Reports normally arrive within two minutes. An empty or failed table is reported explicitly.</p>');$('#copy-discovery-script').onclick=async()=>{await navigator.clipboard.writeText($('#customer-script-source').value);toast('Private discovery script copied');};}catch(error){$('#editor-error').textContent=error.message;}finally{button.disabled=false;}};
}
function customerDisable(id){const router=find('devices',id);if(!router)return;$('#editor-title').textContent='Disable discovery — '+router.name;$('#editor-description').textContent='Revoke this discovery credential. Main router monitoring and customer service continue.';$('#editor-fields').innerHTML='<p>Reports using this discovery script will be rejected. Disable or remove the network-hub-discovery scheduler in WinBox to stop its attempts. Saved observations remain available.</p><label class="check-label"><input type="checkbox" required> Disable customer discovery reporting for this MikroTik.</label>';$('#editor-error').textContent='';$('#editor-form [type=submit]').textContent='Disable reporting';$('#editor').showModal();$('#editor-form').onsubmit=async event=>{event.preventDefault();try{await api('customer-agent/'+id+'/credential','DELETE',{});$('#editor').close();await loadCustomers();toast('Discovery credential revoked');}catch(error){$('#editor-error').textContent=error.message;}};}
document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.customerEnable)customerEnrollment(button.dataset.customerEnable);if(button.dataset.customerDisable)customerDisable(button.dataset.customerDisable);if(button.dataset.customerDetail)customerDetails(button.dataset.customerDetail);if(button.dataset.customerCpe)addCpeFromObservation(button.dataset.customerCpe,button.dataset.existingCpe);if(button.dataset.customerPage){customerView.page=Number(button.dataset.customerPage);loadCustomers();}});
$('#detail-dialog').addEventListener('close',()=>{if($('#customer-script-source'))$('#detail-content').replaceChildren();});
setInterval(()=>{if(state.session?.user&&state.page==='customers'&&!document.hidden&&!$('dialog[open]'))loadCustomers();},15000);
